/**
 * Worker entry: the OpenNext-built Next.js app for requests, plus the cron trigger that retries
 * pending jobs (ADR 0004). Wrangler bundles this file; `.open-next/worker.js` exists after
 * `opennextjs-cloudflare build`.
 */
// @ts-expect-error: generated by the OpenNext build, not present at type-check time.
import nextHandler from './.open-next/worker.js';
import { runScheduled } from './src/server/jobs/scheduled';

export default {
  fetch: (nextHandler as ExportedHandler<CloudflareEnv>).fetch,
  async scheduled(controller, env, ctx) {
    ctx.waitUntil(runScheduled(controller.cron, env));
  },
} satisfies ExportedHandler<CloudflareEnv>;
